"""Full measured-state replay, zero new physics; exact-frame native Peg traces."""
import argparse,json,gzip,hashlib,copy,subprocess
from pathlib import Path
import numpy as np,torch,gymnasium as gym
import mani_skill.envs
from mani_skill.utils import sapien_utils
from PIL import Image,ImageDraw,ImageFont
from program_charger_video_sync import pipe,font
p=argparse.ArgumentParser();p.add_argument('--left',type=Path,required=True);p.add_argument('--right',type=Path,required=True);p.add_argument('--out',type=Path,required=True);p.add_argument('--left-title',default='Same -10mm grasp | original terminal target');p.add_argument('--right-title',default='Identical prefix | measured attachment target');p.add_argument('--comparison-title',default='Peg insertion: same physical prefix');a=p.parse_args();a.out.mkdir(parents=True,exist_ok=False);ds=[json.load(gzip.open(x,'rt'))for x in [a.left,a.right]];seed=ds[0]['summary']['seed'];assert seed==ds[1]['summary']['seed'];assert ds[0]['initial']==ds[1]['initial'];assert all(len(d['steps'])==100 for d in ds)
env=gym.make('PegInsertionSide-v1',num_envs=1,obs_mode='state',control_mode='pd_joint_pos',sim_backend='physx_cuda',render_backend='gpu',render_mode='rgb_array',reconfiguration_freq=1,human_render_camera_configs=dict(mount=None,pose=sapien_utils.look_at([.65,-.65,.5],[-.04,.06,.10]),width=800,height=600,fov=.95));env.reset(seed=seed);u=env.unwrapped;state=copy.deepcopy(u.get_state_dict());assert np.max(np.abs(u.peg.pose.raw_pose[0].cpu().numpy()-ds[0]['initial']['peg']))<1e-6
raw=pipe(a.out/'RAW.mp4',1600,600,20);ann=pipe(a.out/'ANNOTATED.mp4',1600,840,20);data=[];maxerr=0.;colors=['#ffa54f','#54d6e5'];titles=[a.left_title,a.right_title];f=font(21)
for k in range(101):
 canvas=Image.new('RGB',(1600,600));row=[]
 for i,d in enumerate(ds):
  z=d['initial']if k==0 else d['steps'][k-1];ss=copy.deepcopy(state);ss['actors']['peg'][0,:7]=torch.tensor(z['peg'],device='cuda');robot=next(iter(ss['articulations']));ss['articulations'][robot][0,13:22]=torch.tensor(z['q'],device='cuda');ss['articulations'][robot][0,22:31]=torch.tensor(z['qvel'],device='cuda');u.set_state_dict(ss);actual=u.get_state_dict();maxerr=max(maxerr,max(float((ss[g][n]-actual[g][n]).abs().max())for g in ss for n in ss[g]));rgb=u.render_rgb_array()[0].cpu().numpy();canvas.paste(Image.fromarray(rgb),(800*i,0));head=z['evaluation']['peg_head_pos_at_hole'][0];row.append(dict(step=k,phase=z.get('phase','INITIAL'),head=head,lateral_mm=float(np.linalg.norm(head[1:])*1000),grasped=z['grasped'],success=z['evaluation']['success'][0]))
 raw.stdin.write(np.array(canvas).tobytes());pic=Image.new('RGB',(1600,840),'#102030');pic.paste(canvas,(0,70));draw=ImageDraw.Draw(pic);draw.text((12,8),f'PegInsertionSide | step {k}/100 | MEASURED STATE REPLAY | NO NEW RL CLAIM',font=f,fill='white')
 for i,z in enumerate(row):
  draw.text((12+800*i,40),titles[i],font=font(18),fill=colors[i]);draw.text((12+800*i,680),f"{z['phase']} | axial {z['head'][0]*1000:.1f} mm | native {z['success']}",font=font(17),fill=colors[i]);values=[float(v['evaluation']['peg_head_pos_at_hole'][0][0]*1000)for v in [ds[i]['initial']]+ds[i]['steps']];points=[(35+j*15,805-(np.clip(v,-200,100)+200)*.30)for j,v in enumerate(values)];draw.line(points,fill=colors[i],width=2)
 draw.line([(35+k*15,700),(35+k*15,820)],fill='white',width=2);draw.text((12,815),'Axial peg-head position (-200 to +100 mm) | cursor = exact physical frame',font=font(16),fill='white');ann.stdin.write(np.array(pic).tobytes());data.append(row)
 if k==90:canvas.save(a.out/'RAW.png');pic.save(a.out/'ANNOTATED.png')
for proc in [raw,ann]:proc.stdin.close();assert proc.wait()==0
env.close();(a.out/'DATA.json').write_text(json.dumps(data));(a.out/'MANIFEST.json').write_text(json.dumps(dict(seed=seed,physics_steps=0,frames=101,fps=20,max_state_readback_error=maxerr,source_kind='MEASURED_STATE_REPLAY',sources=[dict(path=str(p),sha256=hashlib.sha256(p.read_bytes()).hexdigest())for p in [a.left,a.right]]),indent=2))
(a.out/'SYNC_VIEWER.html').write_text('''<!doctype html><meta charset="utf-8"><title>Peg exact-frame review</title><style>body{background:#102030;color:white;font:18px system-ui;margin:25px}video,canvas{width:95%;max-width:1600px}a{color:cyan}</style><h1>Peg insertion: same physical prefix</h1><video id="v" controls src="ANNOTATED.mp4"></video><p><a href="RAW.mp4">Complete RAW</a> · <a href="MANIFEST.json">Source SHA</a></p><canvas id="c" width="1600" height="200"></canvas><pre id="t"></pre><script>fetch('DATA.json').then(r=>r.json()).then(d=>{const v=document.getElementById('v'),c=document.getElementById('c'),x=c.getContext('2d');function draw(){const k=Math.min(100,Math.round(v.currentTime*20));x.clearRect(0,0,1600,200);['#ffa54f','#54d6e5'].forEach((color,i)=>{x.strokeStyle=color;x.beginPath();d.forEach((r,j)=>{const y=190-(Math.max(-200,Math.min(100,r[i].head[0]*1000))+200)*.6;j?x.lineTo(j*16,y):x.moveTo(0,y)});x.stroke()});x.strokeStyle='white';x.beginPath();x.moveTo(k*16,0);x.lineTo(k*16,200);x.stroke();document.getElementById('t').textContent=JSON.stringify(d[k],null,2);requestAnimationFrame(draw)}c.onclick=e=>v.currentTime=Math.max(0,Math.min(100,Math.round((e.clientX-c.getBoundingClientRect().left)/c.clientWidth*100)))/20;draw()})</script>''')
html=a.out/'SYNC_VIEWER.html';content=html.read_text().replace('Peg insertion: same physical prefix',a.comparison_title).replace("fetch('DATA.json').then(r=>r.json()).then(d=>{",'{const d='+json.dumps(data)+';').replace('})</script>','}</script>');html.write_text(content)
print('Rendered 101 complete frames; pose readback',maxerr)
